#include <optional>
#include <string>
#include <iostream>

std::optional<int> parse(const std::string& s) {
    try { return std::stoi(s); }
    catch (...) { return std::nullopt; }
}

int main() {
    auto result = parse("42")
        .transform([](int n) { return n * 2; })
        .and_then([](int n) -> std::optional<int> {
            if (n > 50) return n;
            return std::nullopt;
        })
        .value_or(-1);

    std::cout << result; // 84
}

