template<class... Ts> struct overloaded : Ts... { using Ts::operator()...; };
template<class... Ts> overloaded(Ts...) -> overloaded<Ts...>;

using Shape = std::variant<int, double, std::string>;

int main() {
    std::vector<Shape> items = {7, 3.14, std::string("hello")};

    for (const auto& item : items) {
        std::visit(overloaded{
            [](int i)                { std::cout << "int " << i << '\n'; },
            [](double d)             { std::cout << "double " << d << '\n'; },
            [](const std::string& s) { std::cout << "string " << s << '\n'; },
        }, item);
    }
}

#include <string_view>
#include <vector>
#include <iostream>

std::vector<std::string_view> split(std::string_view text, char sep) {
    std::vector<std::string_view> parts;
    while (!text.empty()) {
        auto pos = text.find(sep);
        parts.push_back(text.substr(0, pos));
        if (pos == std::string_view::npos) break;
        text.remove_prefix(pos + 1);
    }
    return parts;
}

int main() {
    for (auto word : split("Pune,Bengaluru,Hyderabad,Delhi", ','))
        std::cout << word << '\n'; // no copies, just views
}

#include <iostream>

template<typename... Args>
auto sum(Args... args) {
    return (args + ...);           // unary right fold
}

template<typename... Args>
void print_all(const Args&... args) {
    ((std::cout << args << ' '), ...); // comma fold
    std::cout << '\n';
}

template<typename T, typename... Ts>
bool any_of(const T& value, const Ts&... options) {
    return ((value == options) || ...);
}

int main() {
    std::cout << sum(1, 2, 3, 4.5) << '\n';     // 10.5
    print_all("C++", 17, "folds", '!');          // C++ 17 folds !
    std::cout << std::boolalpha << any_of(3, 1, 2, 3); // true
}

