#include <array>
#include <iostream>

consteval unsigned long long factorial(int n) {
    return n <= 1 ? 1 : n * factorial(n - 1);
}

constexpr auto make_squares() {
    std::array<int, 10> a{};
    for (int i = 0; i < 10; ++i) a[i] = i * i;
    return a;
}

int main() {
    constexpr auto f20 = factorial(20);   // computed by the compiler
    constexpr auto squares = make_squares();
    static_assert(squares[9] == 81);

    std::cout << f20 << '\n';             // 2432902008176640000
    for (int s : squares) std::cout << s << ' ';
}

#include <expected>
