#include <iostream>

enum class ParseError { Empty, NotANumber, Negative };

std::expected<int, ParseError> parse_age(std::string_view s) {
    if (s.empty()) return std::unexpected(ParseError::Empty);
    int value{};
    auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value);
    if (ec != std::errc{} || ptr != s.data() + s.size())
        return std::unexpected(ParseError::NotANumber);
    if (value < 0) return std::unexpected(ParseError::Negative);
    return value;
}

int main() {
    for (std::string_view input : {"29", "", "abc", "-4"}) {
        auto age = parse_age(input);
        if (age) std::cout << "age = " << *age << '\n';
        else     std::cout << "error code " << static_cast<int>(age.error()) << '\n';
    }
}

